import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import test from "node:test";

globalThis.HTMLElement = class {};
globalThis.customElements = {definitions:new Map(),get(name){return this.definitions.get(name);},define(name,value){this.definitions.set(name,value);}};
globalThis.window = {};
globalThis.CustomEvent = class {constructor(type,options){this.type=type;Object.assign(this,options);}};
const fakeElement=localName=>({localName,children:[],attributes:{},listeners:{},append(...children){this.children.push(...children);},setAttribute(name,value){this.attributes[name]=value;},addEventListener(name,listener){this.listeners[name]=listener;}});
globalThis.document = {createElement:fakeElement};
globalThis.fetch = async url => {
  const language=String(url).endsWith("/tasks_strings.json")?"en":String(url).match(/\/([a-z]{2,3})\.json$/)?.[1]||"en";
  const catalog=JSON.parse(readFileSync(new URL(`../../custom_components/tasks/frontend_translations/${language}.json`,import.meta.url),"utf8"));
  return {ok:true,json:async()=>catalog};
};

const {ready,setLanguage}=await import("../../custom_components/tasks/frontend/localize.js");
await ready;
await setLanguage("en");
const {CURRENT_USER,DEFAULT_CARD_CONFIG,TasksCard,UNASSIGNED,dashboardCardBodyHtml,dashboardCardEditorSchema,dashboardTaskRowHtml,dueStatus,filterDashboardTasks,normalizeCardConfig,sortDashboardTasks}=await import("../../custom_components/tasks/frontend/dashboard-card.js");
const {dueDateKey,TasksBase,TasksPanel}=await import("../../custom_components/tasks/frontend/controller.js");
const {TASK_VIEWER_TAG,showTaskViewer}=await import("../../custom_components/tasks/frontend/popup-task-viewer.js");
const {ATTACHMENT_VIEWER_TAG,attachmentPreviewHtml,showAttachmentViewer}=await import("../../custom_components/tasks/frontend/popup-attachment-viewer.js");
const {TASK_EDITOR_TAG,normalizeNotificationTarget,taskEditorFooterHtml,taskField,showTaskEditorPopup}=await import("../../custom_components/tasks/frontend/popup-task-editor.js");
const {CONFIRM_POPUP_TAG,showConfirmation}=await import("../../custom_components/tasks/frontend/popup-confirm.js");
const {createActionMenu}=await import("../../custom_components/tasks/frontend/action-menu.js");
const {taskDetailBoxHtml,taskFilesBoxHtml,taskHistoryBoxHtml}=await import("../../custom_components/tasks/frontend/popup-task-editor.js");

const tasks=[
  {task_id:"old",task_name:"Mopping",task_due:"2026-07-20T12:00:00Z",assignee_id:"alice"},
  {task_id:"today",task_name:"Dishes",task_due:"2026-07-21T12:00:00Z",assignee_id:null},
  {task_id:"soon",task_name:"Bad",task_due:"2026-07-24T12:00:00Z",assignee_id:"bob"},
  {task_id:"later",task_name:"Windows",task_due:"2026-08-01T12:00:00Z",assignee_id:null},
];
const now="2026-07-21T12:00:00Z";

test("default config shows overdue and today",()=>assert.deepEqual(filterDashboardTasks(tasks,DEFAULT_CARD_CONFIG,now).map(task=>task.task_id),["old","today"]));
test("due day window includes its future boundary",()=>assert.deepEqual(filterDashboardTasks(tasks,{due_days:3},now).map(task=>task.task_id),["old","today","soon"]));
test("null due day window includes every due date",()=>assert.equal(filterDashboardTasks(tasks,{due_days:null},now).length,4));
test("inactive tasks are hidden from the dashboard",()=>assert.deepEqual(filterDashboardTasks([...tasks,{...tasks[0],task_id:"paused",active:false}],{due_days:null},now).map(task=>task.task_id),tasks.map(task=>task.task_id)));
test("assignee filter supports multiple selections",()=>assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_ids:["alice",UNASSIGNED]},now).map(task=>task.task_id),["old","today","later"]));
test("assignee filter resolves the logged-in user dynamically",()=>{assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_ids:[CURRENT_USER]},now,undefined,"bob").map(task=>task.task_id),["soon"]);assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_ids:[CURRENT_USER]},now,undefined,"alice").map(task=>task.task_id),["old"]);assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_ids:[CURRENT_USER]},now).map(task=>task.task_id),[]);});
test("YAML assignee filter resolves a Home Assistant user name case-insensitively",()=>{const users=[{id:"alice",name:"Marco"},{id:"bob",name:"Jill"}];assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_filter:"marco"},now,undefined,undefined,users).map(task=>task.task_id),["old"]);assert.deepEqual(filterDashboardTasks(tasks,{due_days:null,assignee_filter:"missing"},now,undefined,undefined,users),[]);});

test("sorting uses absolute timestamps with a name tiebreaker without mutation",()=>{const input=[{task_id:"b",task_name:"Zulu",task_due:"2026-07-21T10:00:00+02:00"},{task_id:"a",task_name:"Alpha",task_due:"2026-07-21T08:00:00Z"},{task_id:"c",task_name:"Later",task_due:"2026-07-21T09:00:00Z"}],original=[...input];assert.deepEqual(sortDashboardTasks(input).map(task=>task.task_id),["a","b","c"]);assert.deepEqual(input,original);});
test("waiting sensor tasks sort after dated tasks and have no due status",()=>{const input=[{task_id:"sensor",task_name:"Problem",task_due:null},{task_id:"dated",task_name:"Dated",task_due:"2026-07-21T12:00:00Z"}];assert.deepEqual(sortDashboardTasks(input).map(task=>task.task_id),["dated","sensor"]);assert.equal(dueStatus(null,now),"");});
test("normalization preserves null, sanitizes invalid values, and removes unsupported options",()=>{assert.equal(normalizeCardConfig({due_days:null}).due_days,null);assert.equal(normalizeCardConfig({due_days:-2}).due_days,0);assert.equal(normalizeCardConfig({sort_direction:"desc",hide_card_background:true}).sort_direction,undefined);assert.equal(normalizeCardConfig({hide_card_background:true}).hide_card_background,undefined);});

test("due status separates overdue, today, and future datetimes",()=>{assert.equal(dueStatus("2026-07-20T12:00:00Z",now),"overdue");assert.equal(dueStatus("2026-07-21T12:00:00Z",now),"today");assert.equal(dueStatus("2026-07-22T12:00:00Z",now),"future");});
test("due datetimes use the displayed time zone for their calendar day",()=>{const localNow="2026-07-24T22:00:00Z";assert.equal(dueDateKey("2026-07-24T23:46:00Z","Europe/Zurich"),"2026-07-25");assert.equal(dueStatus("2026-07-24T23:46:00Z",localNow,"Europe/Zurich"),"today");});
test("dashboard shows the time only for today through the day after tomorrow",()=>{const controller=Object.create(TasksBase.prototype);controller.now="2026-07-25T06:00:00Z";controller._hass={locale:{language:"en-GB",time_zone:"UTC"}};assert.equal(controller.relativeDate("2026-07-25T08:15:00Z"),"today - 08:15");assert.equal(controller.relativeDate("2026-07-26T08:15:00Z"),"tomorrow - 08:15");assert.equal(controller.relativeDate("2026-07-27T08:15:00Z"),"in 2 days - 08:15");assert.equal(controller.relativeDate("2026-07-28T08:15:00Z"),"in 3 days");assert.equal(controller.relativeDate("2026-07-24T08:15:00Z"),"yesterday");});
test("dashboard uses Home Assistant's current list family",()=>{const html=dashboardCardBodyHtml(dashboardTaskRowHtml(tasks[0],false,"yesterday","overdue"),false);assert.match(html,/^<ha-card><ha-list-base/);assert.match(html,/<ha-list-item-button/);assert.match(html,/slot="headline"/);assert.doesNotMatch(html,/role="button"|tabindex=|<ha-list |<ha-list-item /);});
test("view rows use native supporting text without actions",()=>{const html=dashboardTaskRowHtml(tasks[0],false,"yesterday","overdue","Alice","Laundry tag");assert.doesNotMatch(html,/dots-vertical|row-action-toggle|house|ha-assist-chip|row-action-slot/);assert.match(html,/Mopping/);assert.match(html,/class="task-row overdue"/);assert.match(html,/<span slot="supporting-text"><span class="due-date">yesterday<\/span> • Alice • Laundry tag<\/span>/);});
test("dashboard styles only the status icon and due text",()=>{const html=dashboardTaskRowHtml(tasks[0],false,"Today","today");assert.match(html,/class="task-icon" slot="start"/);assert.match(html,/class="due-date">Today/);const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.match(source,/\.task-row\.today \.task-icon,\.task-row\.today \.due-date\{color:var\(--warning-color\)\}/);assert.match(source,/\.task-row\.overdue \.task-icon,\.task-row\.overdue \.due-date\{color:var\(--error-color\)\}/);assert.match(source,/\.task-row\.future \.task-icon,\.task-row\.future \.due-date\{color:var\(--success-color\)\}/);assert.doesNotMatch(source,/themeStyles|pillStyles|taskSurfaceStyles|ha-assist-chip/);});
test("dashboard uses a task icon with the existing icon as fallback",()=>{assert.match(dashboardTaskRowHtml({...tasks[0],task_icon:"mdi:washing-machine"},false,"Today","today"),/icon="mdi:washing-machine"/);assert.match(dashboardTaskRowHtml(tasks[0],false,"Today","today"),/icon="mdi:clipboard-check-outline"/);});
test("dashboard delegates rows to Home Assistant without custom metadata controls",()=>{const dashboard=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8"),list=readFileSync(new URL("../../custom_components/tasks/frontend/sidebar-task-list.js",import.meta.url),"utf8");assert.match(dashboard,/<ha-list-item/);assert.doesNotMatch(dashboard,/<ha-assist-chip/);assert.match(list,/hass-tabs-subpage-data-table/);assert.doesNotMatch(list,/pillStyles\(\)|taskRow\(/);assert.doesNotMatch(dashboard,/pillIconCss\(\)/);});
test("edit rows reserve a native action-menu slot",()=>{const html=dashboardTaskRowHtml(tasks[0],true,"yesterday","overdue");assert.match(html,/class="row-action-slot"/);assert.doesNotMatch(html,/row-action-menu|style=/);});
test("shared action menu puts edit first and dispatches native HA dropdown actions",()=>{let toggled=0,edited=0,removed=0,stopped=0;const menu=createActionMenu({label:"Task actions",active:false,toggleActive:()=>toggled++,edit:()=>edited++,remove:()=>removed++});assert.equal(menu.localName,"ha-dropdown");assert.deepEqual(menu.children.map(child=>child.localName),["ha-icon-button","ha-dropdown-item","ha-dropdown-item","ha-dropdown-item"]);assert.equal(menu.children[0].attributes["aria-label"],"Task actions");assert.equal(menu.children[1].value,"edit");assert.equal(menu.children[2].value,"active");assert.equal(menu.children[3].attributes.variant,"danger");assert.match(menu.children[1].innerHTML,/Edit/);assert.match(menu.children[2].innerHTML,/Activate/);menu.listeners.pointerdown({stopPropagation:()=>stopped++});menu.listeners.click({stopPropagation:()=>stopped++});menu.listeners["wa-select"]({stopPropagation:()=>stopped++,detail:{item:{value:"active"}}});menu.listeners["wa-select"]({stopPropagation:()=>stopped++,detail:{item:{value:"edit"}}});menu.listeners["wa-select"]({stopPropagation:()=>stopped++,detail:{item:{value:"delete"}}});assert.equal(toggled,1);assert.equal(edited,1);assert.equal(removed,1);assert.equal(stopped,5);});
test("dashboard uses Home Assistant's static config form",()=>{const form=TasksCard.getConfigForm(),schema=form.schema,options=schema[0],content=schema[1],filter=schema[2],contentGroup=content.schema[0],dueGroup=filter.schema[0],assigneeGroup=filter.schema[1],secondaryInfo=contentGroup.schema[1],dueDays=dueGroup.schema[1],assigneeFilter=assigneeGroup.schema[1];assert.deepEqual(schema.map(field=>field.name),["options","secondary","filter"]);assert.ok(schema.every(field=>field.type==="expandable"&&field.flatten===true));assert.equal(options.expanded,true);assert.deepEqual(options.schema.map(field=>field.name),["show_action_menu","show_add_task"]);assert.ok(options.schema.every(field=>field.selector.boolean));assert.equal(content.title,"Content");assert.deepEqual([contentGroup,dueGroup,assigneeGroup].map(group=>group.schema[0].type),["constant","constant","constant"]);assert.deepEqual([contentGroup.schema[0].name,dueGroup.schema[0].name,assigneeGroup.schema[0].name],["content_title","due_filter_title","assignee_filter_title"]);assert.equal(secondaryInfo.selector.select.multiple,true);assert.equal(secondaryInfo.selector.select.reorder,true);assert.deepEqual(secondaryInfo.selector.select.options.map(option=>option.value),["due","assignee","nfc_tag","labels"]);assert.equal(dueDays.selector.number.mode,"box");assert.equal(assigneeFilter.default,"all");assert.deepEqual(assigneeFilter.selector.select.options.map(option=>option.value),["all","current_user"]);assert.equal(assigneeFilter.selector.select.options[1].label,"Logged-in user");assert.throws(()=>form.assertConfig({assignee_filter:"Marco"}),/YAML mode/);assert.doesNotThrow(()=>form.assertConfig({assignee_filter:"current_user"}));const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.match(source,/static getConfigForm\(\)/);assert.doesNotMatch(source,/getConfigElement|tasks-card-editor|class TasksCardEditor|createElement\("ha-form"\)/);});
