test("shared controller reloads from Tasks events",async()=>{const controller=Object.create(TasksBase.prototype);controller.eventUnsubscribe=null;controller.eventSubscriptionToken=0;let listener,eventType,loads=0;controller._hass={connection:{subscribeEvents:async(callback,type)=>{listener=callback;eventType=type;return()=>{};}}};controller.load=async()=>{loads++;};await controller.subscribeEvents();assert.equal(eventType,"tasks_event");await listener({data:{action:"updated",resource_type:"task"}});assert.equal(loads,1);});
