test("attachments open through a native popup with media previews and no footer",()=>{let event;const dispatcher={dispatchEvent:value=>{event=value;}};const file={attachment_id:"file",filename:"photo.jpg",content_type:"image/jpeg"};showAttachmentViewer(dispatcher,file,"/signed/file");assert.equal(event.type,"show-dialog");assert.equal(event.detail.dialogTag,ATTACHMENT_VIEWER_TAG);assert.equal(event.detail.dialogParams.file,file);assert.match(attachmentPreviewHtml(file,"/signed/file"),/<img /);assert.match(attachmentPreviewHtml({...file,content_type:"video/mp4"},"/signed/file"),/<video /);assert.match(attachmentPreviewHtml({...file,content_type:"audio/mpeg"},"/signed/file"),/<audio /);assert.match(attachmentPreviewHtml({...file,content_type:"application\/pdf"},"/signed/file"),/<iframe /);const source=readFileSync(new URL("../../custom_components/tasks/frontend/popup-attachment-viewer.js",import.meta.url),"utf8");assert.match(source,/ha-adaptive-dialog/);assert.doesNotMatch(source,/ha-dialog-footer|attachment\.download|class="download"|mdi:download/);});
test("task editor popup does not expose delete actions",()=>{assert.equal(typeof TasksBase.prototype.mountTaskActions,"undefined");});
test("dashboard add action is the final native list row",()=>{const html=dashboardCardBodyHtml('<ha-list-item-button class="task-row"></ha-list-item-button>',true);assert.ok(html.indexOf("add-task")>html.indexOf("task-row"));assert.match(html,/<ha-list-item-button class="add-task"><ha-icon slot="start" icon="mdi:plus"><\/ha-icon><span slot="headline">Add task<\/span><\/ha-list-item-button><\/ha-list-base><\/ha-card>/);const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.match(source,/add\.onclick=\(\)=>\{add\.blur\(\);this\.taskEditor\(null\);\}/);assert.doesNotMatch(source,/border:2px dashed|<ha-button class="add-task"|\.add-task\{/);});

test("dashboard uses native row slots and the shared action menu",()=>{const html=dashboardTaskRowHtml(tasks[0],false,"Today","today","Alex","Tag",["Home","Cleaning"],["assignee","labels","due"]);assert.doesNotMatch(html,/ha-assist-chip|class="task-content"|class="task-meta"/);assert.match(html,/<ha-list-item-button/);assert.match(html,/<span slot="supporting-text">Alex • Home, Cleaning • <span class="due-date">Today<\/span><\/span>/);assert.match(html,/class="task-icon" slot="start"/);const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.match(source,/menu\.slot="end";slot\.replaceWith\(menu\)/);assert.doesNotMatch(source,/style=|themeStyles\(\)|this\.styles\(\)/);});
test("dashboard empty state is a native base row",()=>{const html=dashboardCardBodyHtml("",false);assert.match(html,/^<ha-card><ha-list-base aria-label="Tasks"><ha-list-item-base>/);assert.match(html,/mdi:clipboard-check-outline/);const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.doesNotMatch(source,/style=|themeStyles\(\)|this\.styles\(\)/);});
test("dashboard custom element uses one guarded global registration",()=>{const source=readFileSync(new URL("../../custom_components/tasks/frontend/dashboard-card.js",import.meta.url),"utf8");assert.match(source,/if\(!customElements\.get\("tasks-card"\)\)customElements\.define/);assert.doesNotMatch(source,/tasks-card-editor|browser_mod/i);});
test("row menu deletion relies on the shared change event after the mutation",async()=>{const controller=Object.create(TasksBase.prototype),messages=[];controller.confirmAction=async()=>true;controller.ws=async message=>messages.push(message);let loads=0;controller.load=async()=>{loads++;};await controller.deleteTask({task_id:"task",task_name:"Task"});assert.deepEqual(messages,[{type:"tasks/task/delete",task_id:"task"}]);assert.equal(loads,0);});
